 event_uuid uuid; sheet_uuid uuid; sailor_uuid uuid; result_uuid uuid; item jsonb; race jsonb; fleet text; race_no integer; expected integer; nr integer; class_name text; sheet_slug text; doc text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('sysc-2024-final-results'));
 IF jsonb_array_length(payload)<>265 THEN RAISE EXCEPTION 'Expected 265 boat entries'; END IF;
 INSERT INTO regatta_events(name,slug,start_date,end_date,venue,organizer,classes,nor_url,schedule_summary,scoring_rules)
 VALUES('Singapore Youth Sailing Championships 2024','singapore-youth-sailing-championships-2024','2024-03-09','2024-03-12','National Sailing Centre, Singapore','Singapore Sailing Federation','["Optimist Gold","Optimist Silver","ILCA 4","ILCA 6","29er","Techno 293","iQFOiL"]'::jsonb,'https://www.racingrulesofsailing.org/documents/92416','9–12 March 2024. Final results published 13 March 2024.','Appendix A. Two discards. All classes completed 12 races except iQFOiL, which completed 16.')
 ON CONFLICT(slug) DO UPDATE SET name=excluded.name,start_date=excluded.start_date,end_date=excluded.end_date,venue=excluded.venue,organizer=excluded.organizer,classes=excluded.classes,nor_url=excluded.nor_url,schedule_summary=excluded.schedule_summary,scoring_rules=excluded.scoring_rules,updated_at=now() RETURNING id INTO event_uuid;
 FOR fleet IN SELECT unnest(ARRAY['gold','silver','ilca4','ilca6','29er','techno293','iqfoil']) LOOP
  expected:=CASE fleet WHEN 'gold' THEN 91 WHEN 'silver' THEN 83 WHEN 'ilca4' THEN 52 WHEN 'ilca6' THEN 24 WHEN '29er' THEN 4 WHEN 'techno293' THEN 5 ELSE 6 END;
  nr:=CASE WHEN fleet='iqfoil' THEN 16 ELSE 12 END;
  class_name:=CASE fleet WHEN 'gold' THEN 'Optimist Gold' WHEN 'silver' THEN 'Optimist Silver' WHEN 'ilca4' THEN 'ILCA 4' WHEN 'ilca6' THEN 'ILCA 6' WHEN '29er' THEN '29er' WHEN 'techno293' THEN 'Techno 293' ELSE 'iQFOiL' END;
  sheet_slug:=CASE fleet WHEN 'gold' THEN 'sysc-gold-mar-24-2024-03-09' WHEN 'silver' THEN 'sysc-silver-mar-24-2024-03-09' ELSE 'sysc-2024-'||fleet END;
  doc:='https://drive.google.com/file/d/'||CASE fleet WHEN 'gold' THEN '1MtOGafEFyckcZvHICLUhwphZZA14agYn' WHEN 'silver' THEN '1at9Rd_H_ZT-Afhp7I32GyDoz91zNR7vr' ELSE '1c9ztVlXte_jzuVWZA5pFVdmhQbDVLdxG' END||'/view';
  INSERT INTO regattas(name,slug,date,end_date,total_fleet_size,division,race_count,geography,boat_class,counts_for_ranking,status,event_id,venue,organizer,nor_url,reviewed_at)
  VALUES('Singapore Youth Sailing Championships 2024 ('||class_name||')',sheet_slug,'2024-03-09','2024-03-12',expected,CASE WHEN fleet='gold' THEN 'Gold' WHEN fleet='silver' THEN 'Silver' ELSE 'Open' END,nr,'SGP',CASE WHEN fleet IN ('gold','silver') THEN 'Optimist' ELSE class_name END,fleet IN ('gold','silver','ilca4','ilca6'),'published',event_uuid,'National Sailing Centre, Singapore','Singapore Sailing Federation','https://www.racingrulesofsailing.org/documents/92416',now())
  ON CONFLICT(slug) DO UPDATE SET name=excluded.name,date=excluded.date,end_date=excluded.end_date,total_fleet_size=excluded.total_fleet_size,division=excluded.division,race_count=excluded.race_count,boat_class=excluded.boat_class,counts_for_ranking=excluded.counts_for_ranking,event_id=excluded.event_id,venue=excluded.venue,organizer=excluded.organizer,nor_url=excluded.nor_url,status='published',reviewed_at=now(),updated_at=now() RETURNING id INTO sheet_uuid;
  FOR item IN SELECT value FROM jsonb_array_elements(payload) WHERE value->>'fleet'=fleet LOOP
   IF coalesce((item->>'new_sailor')::boolean,false) THEN
    INSERT INTO sailors(name,handle,sail_number,club,gender) VALUES(item->>'name',item->>'handle',CASE WHEN item->>'sail'='SGP' THEN '0' ELSE coalesce(nullif(item->>'sail',''),'0') END,coalesce(nullif(item->>'club',''),'N/A'),CASE item->>'gender' WHEN 'Male' THEN 'M' WHEN 'Female' THEN 'F' ELSE NULL END) ON CONFLICT(handle) DO NOTHING;
   END IF;
   SELECT id INTO STRICT sailor_uuid FROM sailors WHERE handle=item->>'handle';
   IF item->>'sailor_id' IS NOT NULL AND sailor_uuid<>(item->>'sailor_id')::uuid THEN RAISE EXCEPTION 'Identity changed'; END IF;
   -- Preserve the old result identifier for confirmed misassigned historical rows.
   IF fleet='silver' AND (item->>'rank')::integer IN (26,71) THEN
    UPDATE regatta_results SET sailor_id=sailor_uuid,birth_year=NULL,gender=NULL,nationality=NULL,updated_at=now() WHERE regatta_id=sheet_uuid AND rank=(item->>'rank')::integer AND sailor_id<>sailor_uuid AND NOT EXISTS(SELECT 1 FROM regatta_results WHERE regatta_id=sheet_uuid AND sailor_id=sailor_uuid);
   END IF;
   INSERT INTO regatta_results(sailor_id,regatta_id,rank,nett_score,total_score,gender,nationality,is_dns,is_overseas_commitment,evidence_url,evidence_name,evidence_type,official_url,evidence_notes,verification_status,verified_at)
   VALUES(sailor_uuid,sheet_uuid,(item->>'rank')::integer,(item->>'nett')::real,(item->>'total')::real,CASE item->>'gender' WHEN 'Male' THEN 'M' WHEN 'Female' THEN 'F' ELSE NULL END,item->>'nationality',false,false,doc,'SYSC 2024 '||class_name||' Final Results','link',doc,'Official source name: '||(item->>'name')||'; historical sail: '||(item->>'sail')||'; club: '||(item->>'club')||'; school: '||(item->>'school')||'; division: '||(item->>'division')||'; PDF page: '||(item->>'source_page')||'; two discarded races.','verified',now())
   ON CONFLICT(sailor_id,regatta_id) DO UPDATE SET rank=excluded.rank,nett_score=excluded.nett_score,total_score=excluded.total_score,gender=excluded.gender,nationality=excluded.nationality,is_dns=false,is_overseas_commitment=false,evidence_url=excluded.evidence_url,evidence_name=excluded.evidence_name,evidence_type=excluded.evidence_type,official_url=excluded.official_url,evidence_notes=excluded.evidence_notes,verification_status='verified',verified_at=now(),updated_at=now() RETURNING id INTO result_uuid;
   race_no:=0;
   FOR race IN SELECT value FROM jsonb_array_elements(item->'scores') LOOP
    race_no:=race_no+1;
    INSERT INTO regatta_race_results(regatta_result_id,race_number,score,scoring_code,discarded,raw_value) VALUES(result_uuid,race_no,(race->>'score')::real,race->>'code',(race->>'discarded')::boolean,race->>'raw') ON CONFLICT(regatta_result_id,race_number) DO UPDATE SET score=excluded.score,scoring_code=excluded.scoring_code,discarded=excluded.discarded,raw_value=excluded.raw_value,updated_at=now();
   END LOOP;
   DELETE FROM regatta_race_results WHERE regatta_result_id=result_uuid AND race_number>nr;
   IF race_no<>nr OR EXISTS(SELECT 1 FROM regatta_race_results WHERE regatta_result_id=result_uuid GROUP BY regatta_result_id HAVING sum(score)<>(item->>'total')::real OR sum(score) FILTER(WHERE NOT discarded)<>(item->>'nett')::real OR count(*) FILTER(WHERE discarded)<>2) THEN RAISE EXCEPTION 'Score validation failed: %',item->>'name'; END IF;
  END LOOP;
  DELETE FROM regatta_results r WHERE r.regatta_id=sheet_uuid AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(payload) x JOIN sailors s ON s.handle=x->>'handle' WHERE x->>'fleet'=fleet AND s.id=r.sailor_id);
  IF (SELECT count(*) FROM regatta_results WHERE regatta_id=sheet_uuid)<>expected THEN RAISE EXCEPTION 'Wrong class count: %',fleet; END IF;
 END LOOP;
 INSERT INTO admin_change_log(action,entity_type,entity_id,entity_label,summary,details,source) VALUES('regatta_results_import','regatta_event',event_uuid,'Singapore Youth Sailing Championships 2024','Imported official final results for seven classes: 265 boat entries and 3204 race scores; corrected sailor assignments and restored missing entries.','{"entries":265,"race_scores":3204,"noticeboard":7928}'::jsonb,'official_results_import');
END
$import$;
